STORY = [('silvia', 'Bueno, ¿qué tal, te lo van a dar o no?', 'So how did it go, are they going to give you the part or not?', [(27, 'Bueno, ¿qué tal, te lo van a dar o no?')], ''), ('sofi', 'Yo qué sé, es que me lo han hecho hacer tres veces.', 'How should I know? They made me do it three times.', [(28, 'Yo qué sé, es que me lo han hecho hacer tres veces')], ''), ('sofi', 'Además es un corto precioso sobre una madre joven que lo pasa fatal.', "Besides, it's a lovely short film about a young mother having a terrible time.", [(29, 'además es un corto precioso'), (30, 'lo pasa fatal')], ''), ('silvia', 'Eso es muy actual. Eso está en las noticias todo el día.', "That's very topical. That's on the news all day long.", [(31, 'Eso es muy actual. Eso está en las noticias todo el día')], ''), ('silvia', 'Muy de moda ese papel. ¿Y por qué lloras, corazón?', 'That kind of role is very in style. And why are you crying, sweetheart?', [(32, 'Muy de moda ese papel. ¿Y por qué lloras, corazón?')], ''), ('sofi', 'Que no lloro, es que estoy un poco agobiada.', "I'm not crying, I'm just a bit overwhelmed.", [(33, 'Que no lloro'), (33, 'es que estoy un poco agobiada')], ''), ('silvia', 'Ay, sube la tele, que hablan de los próximos Premios Goya.', "Oh, turn up the TV, they're talking about the upcoming Goya Awards.", [(34, 'Ay, sube la tele'), (51, 'los próximos Premios Goya')], ''), ('mariona', 'Sí, he adelgazado tres kilos porque para la película tuve que engordar diez.', "Yes, I've lost three kilos because for the movie I had to put on ten.", [(57, 'he adelgazado'), (57, 'porque para la película'), (58, 'tuve que engordar')], ''), ('silvia', 'Tú eres mucho más guapa que esa niña, ¿eh?', "You're much prettier than that girl, huh?", [(54, 'Tú eres mucho más guapa que esa niña')], ''), ('sofi', 'Esta lo hace muy bien, tía. Hace lo que le pide el director.', 'She acts really well, girl. She does whatever the director asks of her.', [(55, 'Esta lo hace'), (61, 'Hace lo que le pide el director')], ''), ('silvia', 'Cualquier día estás ahí tú, y yo aquí mirándote. No llores más.', "Any day now you'll be up there, and I'll be right here watching you. Don't cry anymore.", [(63, 'Cualquier día estás ahí tú'), (64, 'No llores más')], ''), ('sofi', '¡Que no!', "I'm not!", [(64, '¡Que no!')], ''), ('silvia', 'Eres muy guapa y te lo mereces. Eres una niña buena.', "You're very pretty and you deserve it. You're a good girl.", [(65, 'Eres muy guapa y te lo mereces'), (65, 'eres una niña buena')], ''), ('sofi', 'Gracias. Ay, que llaman, espera. Dígame.', "Thank you. Oh, the phone's ringing, hold on. Hello?", [(66, 'Gracias. Ay, que llaman, espera'), (67, 'dígame')], '')]
